}

float rand(vec2 n){ return fract(sin(dot(n,vec2(12.9898,4.1414)))*43758.5453); }
float noise(vec2 p){ vec2 ip=floor(p), u=fract(p); u=u*u*(3.0-2.0*u); float r=mix(mix(rand(ip),rand(ip+vec2(1.0,0.0)),u.x),mix(rand(ip+vec2(0.0,1.0)),rand(ip+vec2(1.0,1.0)),u.x),u.y); return r*r; }
const mat2 M=mat2(0.80,0.60,-0.60,0.80);
float fbm(vec2 p,float t){ float f=0.0; f+=0.500000*noise(p+t); p=M*p*2.02; f+=0.031250*noise(p); p=M*p*2.01; f+=0.250000*noise(p); p=M*p*2.03; f+=0.125000*noise(p); p=M*p*2.01; f+=0.062500*noise(p); p=M*p*2.04; f+=0.015625*noise(p+sin(t)); return f/0.96875; }
float pattern(vec2 p,float t){ return fbm(p+fbm(p+fbm(p,t),t),t); }
vec3 colormap(float x){
float r=x<0.0?54.0/255.0:(x<20049.0/82979.0?(829.79*x+54.51)/255.0:1.0);
float g=x<20049.0/82979.0?0.0:(x<327013.0/810990.0?(8546482679670.0/10875673217.0*x-2064961390770.0/10875673217.0)/255.0:(x<=1.0?(103806720.0/483977.0*x+19607415.0/483977.0)/255.0:1.0));
float b=x<0.0?54.0/255.0:(x<7249.0/82979.0?(829.79*x+54.51)/255.0:(x<20049.0/82979.0?127.0/255.0:(x<327013.0/810990.0?(792.0224934*x-64.3647907)/255.0:1.0)));
return vec3(r,g,b);
}
void main(){ vec2 uv=(acScreenNorm*acScreenSize)/acScreenSize.x*scale; float shade=pow(clamp(pattern(uv,time*speed),0.0,1.0),1.0/contrast); vec3 src=texture2DCv(inputImg.texture,acScreenNorm).rgb; gl_FragColor=vec4(mix(colormap(shade),src,sourceMix),1.0);
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}

float gAsp = 1.0;
float gT   = 0.0;

vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }

// LAYER -> SCREEN. The field and the falloff are both measured in layer space,
// so the split deforms the layer's own pixels and follows it around.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }

vec2 edgeFix(vec2 lp){
if (edgeMode <= 0) return clamp(lp, 0.0, 1.0);
if (edgeMode <= 1){
vec2 m = mod(lp, vec2(2.0, 2.0));
return abs(m - vec2(1.0, 1.0)) * -1.0 + vec2(1.0);
}
return fract(lp);
}
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(edgeFix(lp)), 0.0, 1.0)); }

float h21(vec2 p){ return fract(sin(dot(p + seed * 3.7, vec2(127.1, 311.7))) * 43758.5453123); }
float vnoise2(vec2 p){
vec2 i = floor(p);
vec2 f = fract(p);
f = f * f * (3.0 - 2.0 * f);
return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), f.x),
           mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), f.x), f.y);
}
float fbm2(vec2 p){
float s = 0.0;
float amp = 0.5;
for (int i = 0; i < 6; i++){
if (float(i) >= float(complexity)) break;
s += amp * vnoise2(p);
p *= 2.07;
amp *= 0.5;
}
return s;
}

// The warp field, returned in aspect-corrected layer units.
vec2 warpAt(vec2 p){
float ra = radians(angle);
vec2  ax = vec2(cos(ra), sin(ra));
vec2  ay = vec2(-ax.y, ax.x);
vec2  q  = vec2(dot(p, ax), dot(p, ay));

if (warpType <= 0){
// Curl of the fbm. Taking the perpendicular of the gradient gives a field with
// no divergence, so it swirls and folds instead of squashing everything into
// sinks - that is what makes the separation read as dispersion.
float e  = 0.012;
float fx = fbm2((p + vec2(e, 0.0)) * scale + gT) - fbm2((p - vec2(e, 0.0)) * scale + gT);
float fy = fbm2((p + vec2(0.0, e)) * scale + gT) - fbm2((p - vec2(0.0, e)) * scale + gT);
return vec2(fy, -fx) / max(e, 1.0e-5) * 0.02;
} else if (warpType <= 1){
return vec2(sin(q.y * scale * 3.0 + gT * 2.0),
            sin(q.x * scale * 2.2 - gT * 1.4)) * 0.5;
} else if (warpType <= 2){
float r = max(length(q), 1.0e-4);
return (vec2(-q.y, q.x) / r) * sin(r * scale * 2.0 + gT * 2.0) * smoothstep(0.0, 0.3, r);
} else if (warpType <= 3){
float r = max(length(q), 1.0e-4);
return (q / r) * exp(-r * r * scale * 1.2) * (0.6 + 0.4 * sin(gT));
} else if (warpType <= 4){
float r = max(length(q), 1.0e-4);
return (q / r) * sin(r * scale * 4.0 - gT * 3.0) * exp(-r * 1.6);
}
float r = max(length(q), 1.0e-4);
return (q / r) * r * 0.5;
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float al = max(src.a, 1.0e-4);
vec3 sc = src.rgb / al;

gAsp = acLayerSize.x / max(acLayerSize.y, 1.0);
gT   = speed * acTime;

vec2 p = lp - vec2(0.5);
p.x *= gAsp;

vec2 c0 = centre - vec2(0.5);
c0.x *= gAsp;
vec2 rel = p - c0;

vec2 w = warpAt(p);

// ---- split mode ---------------------------------------------------------
// Every mode ends up as one extra displacement vector, so the per-channel
// multipliers below stay the single place where the split is decided.
vec2 extra = vec2(0.0);
if (chromaMode >= 1 && chromaMode <= 1){
// Radial dispersion: separation grows with distance from the centre, the way a
// real lens spreads the channels toward the corners.
float rl = max(length(rel), 1.0e-4);
extra = (rel / rl) * rl * dispersion;
} else if (chromaMode >= 2 && chromaMode <= 2){
extra = vec2(1.0, 0.0) * dispersion;
} else if (chromaMode >= 3){
float rl = max(length(rel), 1.0e-4);
extra = (vec2(-rel.y, rel.x) / rl) * rl * dispersion;
}

// ---- falloff ------------------------------------------------------------
float d    = length(rel);
float gain = 1.0 - falloff * smoothstep(0.0, max(falloffWidth, 0.02), d);

vec2 disp = (w * gain + extra);

// ---- per-channel displacement ------------------------------------------
// One field, three multipliers. Green at zero keeps one channel anchored, so
// the fringing reads as dispersion rather than as three copies of the picture.
vec4 got;
got.r = fetchL(lp + disp * amount * rScale).r;
got.g = fetchL(lp + disp * amount * gScale).g;
got.b = fetchL(lp + disp * amount * bScale).b;
got.a = fetchL(lp).a;

vec3 col = sat3v(mix(sc, got.rgb, mixAmt));
float oA = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}

#define PI 3.14159265359
mat2 rot(float a) {
float s = sin(a), c = cos(a);
return mat2(c, -s, s, c);
}
float sdHex(vec2 p, float r) {
const vec3 k = vec3(-0.866025404, 0.5, 0.577350269);
p = abs(p);
p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
p -= vec2(clamp(p.x, -k.z * r, k.z * r), r);
return length(p) * sign(p.y);
}
void main() {
vec2 uv = acLayerNorm;
vec4 original = texture2DCv(inputImg.texture, uv);
vec2 st = (uv - 0.5) * 2.0;
st.x *= acLayerSize.x / max(acLayerSize.y, 1.0);
st *= rot(rotZ * (PI / 180.0));
float scale = complexity * 2.0;
vec2 grid = fract(st * scale) - 0.5;
vec2 id = floor(st * scale);
vec2 offset3D = vec2(sin(rotY * (PI / 180.0)), sin(rotX * (PI / 180.0))) * 0.2;
float d1 = abs(sdHex(grid + offset3D, 0.4)) - thickness;
float d2 = abs(sdHex(grid * rot(PI/6.0) - offset3D, 0.3)) - thickness;
float d3 = abs(length(grid) - 0.2) - thickness;
float minD = min(min(d1, d2), d3);
float lineAlpha = smoothstep(0.02, 0.0, minD);
float glowAlpha = exp(-minD * 8.0) * 0.5;
vec3 color = mix(original.rgb, glowColor.rgb, glowAlpha * glowColor.a);
color = mix(color, lineColor.rgb, lineAlpha * lineColor.a);
float totalAlpha = max(original.a, max(lineAlpha * lineColor.a, glowAlpha * glowColor.a));
color *= totalAlpha;
gl_FragColor = vec4(color, totalAlpha);
}
